// Custom PDF Parser for "GNO Hesaplayıcı | Pro" format
// This format is generated by the app itself or a specific tool.

function extractCustomFormat(pages) {
    const fullText = pages.join("\n");
    if (!fullText.includes("GNO Hesaplayıcı") && !fullText.includes("AKTS Modu") && !fullText.includes("UK (Kredi) Modu")) {
        return [];
    }

    const mode = fullText.includes("UK (Kredi) Modu") ? "UK" : "AKTS";
    let currentSemester = "Geri Yüklenen";
    let indexCounter = 0;
    const extracted = [];

    pages.forEach(pageText => {
        const lines = pageText.split('\n');
        lines.forEach(line => {
            line = line.trim();
            if (!line) return;

            if (line.includes("DNO:")) {
                const parts = line.split("DNO:");
                const sem = parts[0].trim();
                // Remove calendar icon if present (unicode usually)
                if (sem) currentSemester = sem.replace(/[^\w\s\d-]/g, "").trim();
                return;
            }

            const parts = line.split(/\s+/);
            if (parts.length < 3) return;

            const grade = parts[parts.length - 1];
            // Grade validation (short)
            if (grade.length > 3 && grade !== "Başarılı" && grade !== "Başarısız") return;

            const creditStr = parts[parts.length - 2];
            if (!/^\d+(\.\d+)?$/.test(creditStr)) return;

            const code = parts[0];
            if (!/\d/.test(code)) return; // Code usually has digits

            // Name is everything between Code and Credit
            const nameTokens = parts.slice(1, parts.length - 2);
            const name = nameTokens.join(" ");

            const val = parseFloat(creditStr);
            const akts = mode === "AKTS" ? Math.round(val) : 0;
            const uk = mode === "UK" ? val : 0;

            extracted.push({
                id: indexCounter++,
                semester: currentSemester,
                code: code,
                name: name,
                akts: akts,
                uk: uk,
                grade: grade,
                status: 'Z'
            });
        });
    });
    return extracted;
}

// Export for Node.js testing if module.exports is available
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { extractCustomFormat };
}
